window.MM = window.MM || {};
window.MM['anaes_p2_pharma_ans'] = [
  {"q":"Which neurotransmitter is released by all preganglionic autonomic nerve fibres?","o":["Dopamine","Acetylcholine","Norepinephrine","Epinephrine"],"a":1,"e":"All preganglionic autonomic neurons (both sympathetic and parasympathetic) release acetylcholine, which acts on nicotinic (Nn) receptors in autonomic ganglia.<br><br><strong>Take Notes:</strong><br>• ALL preganglionic fibres → ACh (nicotinic Nn receptor)<br>• Sympathetic postganglionic → NE (usually)<br>• Parasympathetic postganglionic → ACh (muscarinic)<br>⚡ Exception: Sweat glands = Sympathetic + Cholinergic"},
  {"q":"The principal neurotransmitter released from most postganglionic sympathetic nerve endings is:","o":["Acetylcholine","Dopamine","Norepinephrine","Serotonin"],"a":2,"e":"Most postganglionic sympathetic neurons release norepinephrine onto adrenergic receptors of target organs — with the notable exception of sweat glands which receive cholinergic sympathetic fibres.<br><br><strong>Take Notes:</strong><br>• Postganglionic sympathetic: NE (most)<br>⚡ Exception: Sweat glands → ACh (cholinergic sympathetic)<br>⚡ Adrenal medulla: Directly innervated by preganglionic → Releases Epi + NE"},
  {"q":"Which receptor subtype is primarily responsible for increasing heart rate?","o":["α1 receptor","α2 receptor","β1 receptor","β2 receptor"],"a":2,"e":"β1 receptors are the dominant adrenergic receptors in the SA node and cardiac conduction system, mediating positive chronotropy, inotropy and dromotropy.<br><br><strong>Take Notes:</strong><br>• β1 = Heart (mnemonic: 1 heart)<br>• Chronotropy ↑ (HR) | Inotropy ↑ (force) | Dromotropy ↑ (conduction)<br>• Also: Renin ↑ from JG cells"},
  {"q":"Stimulation of α1 receptors produces:","o":["Bronchodilation","Vasodilation","Vasoconstriction","Bradycardia"],"a":2,"e":"α1 receptors are the principal postsynaptic receptors of vascular smooth muscle; their activation via Gq-protein causes smooth muscle contraction and vasoconstriction.<br><br><strong>Take Notes:</strong><br>• α1 effects:<br>• Vasoconstriction ↑ SVR | Mydriasis (radial iris muscle)<br>• Bladder sphincter contraction | Ureter contraction<br>⚡ α1 blockers (prazosin): Vasodilation + Postural hypotension"},
  {"q":"Which receptor subtype mediates bronchodilation?","o":["α1 receptor","β1 receptor","β2 receptor","M2 receptor"],"a":2,"e":"β2 receptor activation via Gs/cAMP relaxes bronchial smooth muscle — the mechanism exploited by salbutamol, terbutaline and other bronchodilators.<br><br><strong>Take Notes:</strong><br>• β2 effects:<br>• Bronchodilation | Uterine relaxation<br>• Vasodilation (skeletal muscle) | Glycogenolysis ↑<br>• Insulin ↑ | K⁺ into cells ↑<br>✅ Salbutamol = Selective β2 agonist"},
  {"q":"Atropine acts primarily by:","o":["Stimulating muscarinic receptors","Blocking muscarinic receptors","Blocking nicotinic receptors","Stimulating α receptors"],"a":1,"e":"Atropine is a competitive, reversible muscarinic antagonist — blocking all muscarinic subtypes (M1–M5) and eliminating parasympathetic effects on target organs.<br><br><strong>Take Notes:</strong><br>• Atropine: Competitive muscarinic antagonist<br>• HR ↑ | Secretions ↓ | Bronchodilation<br>• Mydriasis + Cycloplegia | Urinary retention<br>⚠️ Crosses BBB (tertiary amine) → CNS effects"},
  {"q":"Which drug is commonly used during anaesthesia to treat symptomatic bradycardia?","o":["Propranolol","Phenylephrine","Atropine","Prazosin"],"a":2,"e":"Atropine blocks vagal muscarinic input to the SA node, removing the parasympathetic brake on heart rate — the first-line drug for sinus bradycardia during anaesthesia.<br><br><strong>Take Notes:</strong><br>• Bradycardia treatment: Atropine<br>• Dose: 0.5–1 mg IV (adult) | 0.02 mg/kg (child)<br>• Minimum dose (child): 0.1 mg to avoid paradoxical bradycardia<br>✅ Alternative: Glycopyrrolate 0.2 mg IV"},
  {"q":"Phenylephrine is a selective:","o":["α1 agonist","β1 agonist","β2 agonist","Muscarinic agonist"],"a":0,"e":"Phenylephrine is a pure α1 adrenergic agonist causing arterial vasoconstriction, raising SVR and MAP without direct cardiac stimulation — hence reflex bradycardia commonly occurs.<br><br><strong>Take Notes:</strong><br>• Phenylephrine: Pure α1 agonist<br>• SVR ↑ | BP ↑ | Reflex bradycardia<br>• CO unchanged or ↓<br>✅ Spinal/epidural hypotension vasopressor | Ophthalmology"},
  {"q":"Which adrenergic receptor is located presynaptically and inhibits norepinephrine release?","o":["α1 receptor","α2 receptor","β1 receptor","β2 receptor"],"a":1,"e":"Presynaptic α2 autoreceptors provide negative feedback — when activated by released NE, they inhibit further NE exocytosis, modulating sympathetic tone.<br><br><strong>Take Notes:</strong><br>• α2 presynaptic: NE release ↓ (autoreceptor negative feedback)<br>• α2 postsynaptic (CNS): Sympathetic outflow ↓ → Clonidine mechanism<br>• Pancreas: Insulin ↓"},
  {"q":"Clonidine primarily acts as a:","o":["β1 agonist","α1 antagonist","α2 agonist","Muscarinic antagonist"],"a":2,"e":"Clonidine stimulates central α2 receptors (especially in the nucleus tractus solitarius and locus coeruleus), reducing sympathetic outflow and lowering BP, HR and anxiety.<br><br><strong>Take Notes:</strong><br>• Clonidine: Central α2 agonist<br>• Sympatholysis: BP ↓ | HR ↓<br>• Sedation | Analgesia | MAC ↓<br>⚠️ Abrupt withdrawal → Rebound severe hypertension"},
  {"q":"Which drug is a nonselective β-adrenergic antagonist?","o":["Atenolol","Metoprolol","Propranolol","Esmolol"],"a":2,"e":"Propranolol blocks both β1 (cardiac) and β2 (bronchial, vascular) receptors — making it contraindicated in asthma and bronchospasm-prone patients.<br><br><strong>Take Notes:</strong><br>• Propranolol: Non-selective β1 + β2 blocker<br>⚠️ Contraindicated: Asthma | COPD<br>⚡ Selective β1: Atenolol | Metoprolol | Bisoprolol | Esmolol<br>✅ Propranolol also: Thyrotoxicosis | Tremor | Portal HTN"},
  {"q":"Which β-blocker has the shortest duration of action and is commonly used intraoperatively?","o":["Atenolol","Metoprolol","Esmolol","Propranolol"],"a":2,"e":"Esmolol is rapidly hydrolysed by red blood cell esterases (t½ ≈9 min), making it ideal for precise intraoperative titration of heart rate.<br><br><strong>Take Notes:</strong><br>• Esmolol: Ultra-short β1 blocker<br>• t½ ≈9 min | Ester hydrolysis in RBCs<br>✅ Intraoperative HR control | Laryngoscopy response | Emergence HTN<br>→ NOT hepatic/renal dependent"},
  {"q":"Activation of muscarinic M2 receptors in the heart causes:","o":["Tachycardia","Increased contractility","Bradycardia","Vasoconstriction"],"a":2,"e":"M2 muscarinic receptors in the SA node couple to Gi-proteins, reducing cAMP and decreasing automaticity — the molecular basis of vagal bradycardia.<br><br><strong>Take Notes:</strong><br>• M2 effects (cardiac):<br>• SA node: HR ↓ (negative chronotropy)<br>• AV node: Conduction ↓ (negative dromotropy)<br>⚡ Atropine blocks M2 → HR ↑"},
  {"q":"Which drug is most commonly used to reverse nondepolarising neuromuscular blockade together with glycopyrrolate?","o":["Atropine","Neostigmine","Prazosin","Dobutamine"],"a":1,"e":"Neostigmine inhibits acetylcholinesterase, increasing ACh at the NMJ to compete with residual NMB — glycopyrrolate is co-administered to prevent muscarinic side effects.<br><br><strong>Take Notes:</strong><br>• Neostigmine + Glycopyrrolate: Reversal pair<br>• Neostigmine: AChE inhibitor → ACh ↑ at NMJ<br>• Glycopyrrolate: Blocks muscarinic side effects (bradycardia)<br>⚡ Sugammadex: Direct encapsulation of rocuronium/vecuronium"},
  {"q":"Glycopyrrolate differs from atropine because it:","o":["Crosses the blood-brain barrier readily","Is a β-blocker","Produces minimal CNS effects","Causes severe sedation"],"a":2,"e":"Glycopyrrolate is a quaternary ammonium compound — its permanent positive charge prevents crossing the lipid blood-brain barrier, eliminating CNS stimulation or sedation.<br><br><strong>Take Notes:</strong><br>• Glycopyrrolate: Quaternary ammonium → Cannot cross BBB<br>• No CNS effects | Less tachycardia than atropine<br>✅ Preferred with neostigmine | Antisialagogue premedication<br>⚡ Atropine: Tertiary → Crosses BBB freely"},
  {"q":"Which drug directly stimulates β1 receptors and increases cardiac contractility?","o":["Dobutamine","Phenylephrine","Prazosin","Atropine"],"a":0,"e":"Dobutamine is a synthetic catecholamine with predominantly β1 agonist activity — increasing contractility and cardiac output with relatively little change in SVR or HR.<br><br><strong>Take Notes:</strong><br>• Dobutamine: β1 agonist (inotrope)<br>• CO ↑ | Contractility ↑ | SVR minimal change<br>✅ Acute cardiac failure | Cardiogenic shock<br>⚠️ MVO₂ ↑ — use cautiously in IHD"},
  {"q":"Which drug is most likely to cause reflex bradycardia?","o":["Phenylephrine","Dobutamine","Isoproterenol","Ephedrine"],"a":0,"e":"Phenylephrine's pure α1 stimulation raises arterial pressure without a direct cardiac effect — activating baroreceptors which trigger reflex vagal bradycardia.<br><br><strong>Take Notes:</strong><br>• Phenylephrine: Reflex bradycardia<br>• BP ↑ via SVR → Baroreceptors → Vagal ↑ → HR ↓<br>⚠️ Can worsen bradycardia in susceptible patients<br>✅ Advantage: No tachycardia | Preserves uteroplacental flow (obstetric)"},
  {"q":"Ephedrine increases blood pressure primarily by:","o":["Pure α1 stimulation","Releasing norepinephrine and direct receptor stimulation","Muscarinic blockade","Cholinesterase inhibition"],"a":1,"e":"Ephedrine is a mixed-acting sympathomimetic — it releases endogenous NE from nerve terminals (indirect) AND directly stimulates adrenergic receptors, affecting both α and β subtypes.<br><br><strong>Take Notes:</strong><br>• Ephedrine: Mixed-acting sympathomimetic<br>• Indirect: NE release from terminals<br>• Direct: α + β stimulation → HR ↑ + BP ↑ + CO ↑<br>⚠️ Tachyphylaxis with repeated doses (NE stores depleted)"},
  {"q":"Which receptor subtype is responsible for relaxation of uterine smooth muscle?","o":["α1 receptor","β1 receptor","β2 receptor","M3 receptor"],"a":2,"e":"β2 receptor activation relaxes uterine smooth muscle (tocolytic effect) — this property is exploited by ritodrine and salbutamol to arrest premature labour.<br><br><strong>Take Notes:</strong><br>• β2 uterine effects:<br>• Uterine relaxation (tocolysis)<br>✅ Drugs: Ritodrine | Salbutamol | Terbutaline for preterm labour<br>⚡ α1 (oxytocin) → Uterine contraction"},
  {"q":"Which muscarinic receptor subtype primarily stimulates glandular secretion?","o":["M1/M3 receptors","β1 receptors","α2 receptors","β2 receptors"],"a":0,"e":"M3 receptors on exocrine glands activate Gq/PLC signalling, increasing intracellular Ca²⁺ and stimulating secretion of saliva, gastric acid, pancreatic juice and lacrimal fluid.<br><br><strong>Take Notes:</strong><br>• M3 glandular effects:<br>• Salivation ↑ | Lacrimation ↑ | Sweating ↑<br>• Gastric acid ↑ | Pancreatic secretion ↑<br>✅ Atropine/Glycopyrrolate block M3 → Dry mouth/secretions"},
  {"q":"Prazosin is a selective antagonist of:","o":["α1 receptors","α2 receptors","β1 receptors","M2 receptors"],"a":0,"e":"Prazosin selectively blocks postsynaptic α1 receptors causing peripheral vasodilation — used for hypertension and, importantly, as the α-blocker of choice in phaeochromocytoma treatment.<br><br><strong>Take Notes:</strong><br>• Prazosin: Selective α1 antagonist<br>• SVR ↓ → BP ↓<br>• Reflex tachycardia (less than non-selective)<br>⚡ Phenoxybenzamine: Non-selective, irreversible α blocker (phaeochromocytoma prep)"},
  {"q":"Which catecholamine predominantly stimulates β1 receptors at low doses?","o":["Phenylephrine","Dobutamine","Prazosin","Glycopyrrolate"],"a":1,"e":"Dobutamine is primarily a β1 agonist producing positive inotropy — it increases cardiac output with relatively minimal chronotropy or SVR changes at usual clinical doses.<br><br><strong>Take Notes:</strong><br>• Dobutamine: β1 dominant<br>• CO ↑ | Contractility ↑<br>• SVR: Minimal change or ↓ (β2 effect)<br>✅ Cardiogenic shock | Decompensated cardiac failure | Cardiac stress testing"},
  {"q":"Which drug produces mydriasis without cycloplegia?","o":["Phenylephrine","Atropine","Tropicamide","Scopolamine"],"a":0,"e":"Phenylephrine contracts the radial (dilator) muscle of the iris via α1 receptors — producing mydriasis but NOT affecting the ciliary muscle, so accommodation is preserved.<br><br><strong>Take Notes:</strong><br>• Phenylephrine (ophthalmic):<br>• Mydriasis (α1 → dilator iris muscle)<br>• NO cycloplegia (ciliary muscle unaffected)<br>⚡ Atropine/Tropicamide: Mydriasis + Cycloplegia (M block)"},
  {"q":"Which autonomic drug is commonly used to reduce oral and airway secretions before anaesthesia?","o":["Propranolol","Glycopyrrolate","Dobutamine","Prazosin"],"a":1,"e":"Glycopyrrolate is the preferred antisialagogue for premedication — blocking M3 glandular receptors to reduce salivary, bronchial and gastric secretions without CNS penetration.<br><br><strong>Take Notes:</strong><br>• Glycopyrrolate as antisialagogue:<br>• M3 blockade → Secretions ↓<br>• No CNS effects (quaternary ammonium)<br>✅ Dose: 0.2 mg IV | Combined with neostigmine for reversal"},
  {"q":"Isoproterenol stimulates:","o":["α1 and α2 receptors","β1 and β2 receptors","Muscarinic receptors","Dopamine receptors only"],"a":1,"e":"Isoproterenol is a synthetic non-selective β agonist with essentially no α activity — producing cardiac stimulation (β1) and vasodilation/bronchodilation (β2) simultaneously.<br><br><strong>Take Notes:</strong><br>• Isoproterenol: Non-selective β1 + β2<br>• HR ↑↑ | Contractility ↑ | SVR ↓ | Bronchodilation<br>✅ Complete heart block (before pacing) | Torsades de pointes<br>⚠️ BP may fall (SVR ↓ > CO ↑)"},
  {"q":"Which drug is commonly used as a vasopressor during spinal anaesthesia-induced hypotension?","o":["Phenylephrine","Propranolol","Atropine","Prazosin"],"a":0,"e":"Phenylephrine is the most commonly recommended first-line vasopressor for spinal-induced hypotension — particularly in obstetrics, where it preserves uteroplacental perfusion better than ephedrine.<br><br><strong>Take Notes:</strong><br>• Spinal hypotension: Phenylephrine preferred<br>• Pure α1 → SVR ↑ | BP restored<br>• Obstetric advantage: Better fetal acid-base vs ephedrine<br>⚠️ Reflex bradycardia: Treat with atropine if symptomatic"},
  {"q":"Which muscarinic antagonist crosses the blood-brain barrier most readily?","o":["Glycopyrrolate","Atropine","Neostigmine","Edrophonium"],"a":1,"e":"Atropine is a tertiary amine — it is lipid-soluble and readily penetrates the blood-brain barrier, producing CNS effects (sedation, confusion, hallucinations at high doses).<br><br><strong>Take Notes:</strong><br>• BBB crossing: Atropine (tertiary amine)<br>• CNS effects: Sedation at low dose | Agitation/delirium at high dose<br>⚡ Glycopyrrolate: Quaternary → BBB impermeable<br>✅ Physostigmine: Reverses central anticholinergic syndrome"},
  {"q":"Which autonomic receptor is primarily responsible for vasoconstriction of skin blood vessels?","o":["α1 receptor","β1 receptor","β2 receptor","M2 receptor"],"a":0,"e":"α1 receptors are the principal mediators of cutaneous vasoconstriction — activated during sympathetic arousal to divert blood flow from skin to vital organs.<br><br><strong>Take Notes:</strong><br>• α1: Cutaneous vasoconstriction<br>• Diverts blood to vital organs in fight-or-flight<br>• Phenylephrine/Norepinephrine → SVR ↑ via this receptor"},
  {"q":"Which drug is most useful for treating severe vagally mediated bradycardia during anaesthesia?","o":["Prazosin","Phenylephrine","Atropine","Propranolol"],"a":2,"e":"Atropine blocks M2 receptors at the SA node, removing excessive vagal inhibition and promptly restoring heart rate during vagally mediated bradycardia (e.g., from peritoneal traction, carotid stimulation).<br><br><strong>Take Notes:</strong><br>• Vagal bradycardia: Atropine<br>• Mechanism: M2 blockade → SA node released from vagal inhibition<br>• Dose: 0.5–1 mg IV | Repeatable<br>✅ Also: Glycopyrrolate 0.2–0.4 mg IV"},
  {"q":"During anaesthesia, a patient develops profound hypotension after spinal anaesthesia. The anaesthesiologist administers a pure α1 agonist. Which drug was most likely given?","o":["Dobutamine","Glycopyrrolate","Isoproterenol","Phenylephrine"],"a":3,"e":"Phenylephrine is the cornerstone vasopressor in neuraxial anaesthesia hypotension — its pure α1 action directly restores SVR and MAP without cardiac stimulation.<br><br><strong>Take Notes:</strong><br>• Spinal hypotension vasopressor: Phenylephrine<br>• Pure α1 → SVR ↑ | No direct cardiac effect<br>• Preferred in obstetrics (better fetal pH)<br>✅ Dose: 50–100 μg IV bolus | Infusion: 25–100 μg/min"},
  {"q":"Which adrenergic receptor is primarily responsible for renin release from the juxtaglomerular apparatus?","o":["α1 receptor","α2 receptor","β1 receptor","β2 receptor"],"a":2,"e":"β1 receptors on juxtaglomerular cells respond to sympathetic stimulation by releasing renin, activating the RAAS — relevant when β-blockers suppress this response and lower renin-dependent hypertension.<br><br><strong>Take Notes:</strong><br>• β1: Renin ↑ from JG apparatus<br>• β-blockers: Renin ↓ → Additional antihypertensive mechanism<br>• β1 also: Heart (inotropy + chronotropy)"},
  {"q":"Which vasopressor commonly used in anaesthesia acts mainly through indirect release of norepinephrine?","o":["Phenylephrine","Ephedrine","Vasopressin","Dobutamine"],"a":1,"e":"Ephedrine displaces NE from presynaptic vesicles and stimulates its release (indirect), while also having some direct α/β agonist activity — giving it a mixed sympathomimetic profile.<br><br><strong>Take Notes:</strong><br>• Ephedrine: Mixed-acting sympathomimetic<br>• Indirect: Displaces NE from nerve terminals<br>• Direct: α + β stimulation<br>⚠️ Tachyphylaxis: NE stores deplete with repeated use"},
  {"q":"Which autonomic drug is most likely to produce dry mouth, blurred vision, tachycardia, and urinary retention?","o":["Neostigmine","Atropine","Phenylephrine","Clonidine"],"a":1,"e":"These four symptoms constitute the classic antimuscarinic toxidrome ('Mad as a hatter, Dry as a bone, Blind as a bat, Red as a beet') from M1–M3 receptor blockade throughout the body.<br><br><strong>Take Notes:</strong><br>• Antimuscarinic syndrome: Atropine<br>• Dry mouth (M3) | Tachycardia (M2) | Urinary retention (M3)<br>• Blurred vision/Mydriasis (M3) | Hot flushed skin<br>✅ Antidote: Physostigmine (crosses BBB)"},
  {"q":"Which adrenergic agonist increases blood pressure predominantly by increasing cardiac output rather than SVR?","o":["Phenylephrine","Norepinephrine","Dobutamine","Vasopressin"],"a":2,"e":"Dobutamine raises CO through β1 inotropy with minimal α1-mediated SVR increase — the mechanism for its use in low-output heart failure states.<br><br><strong>Take Notes:</strong><br>• Dobutamine: CO ↑ (inotrope) → BP ↑<br>• Mechanism: β1 → Contractility ↑ + CO ↑<br>⚡ Phenylephrine: SVR ↑ → BP ↑ (opposite mechanism)<br>✅ Dobutamine: Cardiogenic shock | Not septic shock"},
  {"q":"Which cholinesterase inhibitor has the shortest duration of action?","o":["Pyridostigmine","Neostigmine","Edrophonium","Physostigmine"],"a":2,"e":"Edrophonium binds reversibly and electrostatically to AChE via its quaternary nitrogen — this weak, non-covalent bond dissociates rapidly, producing the shortest duration of all AChE inhibitors.<br><br><strong>Take Notes:</strong><br>• AChE inhibitors (shortest → longest):<br>• Edrophonium ≈5–15 min<br>• Neostigmine ≈45–90 min<br>• Pyridostigmine ≈90–180 min<br>• Physostigmine ≈1–2h"},
  {"q":"Which receptor subtype is mainly responsible for contraction of the urinary bladder detrusor muscle?","o":["M1 receptor","M2 receptor","M3 receptor","β1 receptor"],"a":2,"e":"M3 receptors on detrusor smooth muscle contract the bladder during micturition — blocked by antimuscarinics such as oxybutynin and tolterodine for overactive bladder treatment.<br><br><strong>Take Notes:</strong><br>• M3: Detrusor contraction → Micturition<br>• M3 blockade: Antimuscarinic drugs → Urinary retention risk<br>✅ Anticholinergics in elderly: Urinary retention + Confusion"},
  {"q":"Norepinephrine differs from epinephrine because norepinephrine has relatively little activity at:","o":["α1 receptors","α2 receptors","β1 receptors","β2 receptors"],"a":3,"e":"Norepinephrine has potent α1 and α2 activity and moderate β1 activity, but negligible β2 activity — explaining its lack of bronchodilation and its SVR-increasing profile without peripheral vasodilation.<br><br><strong>Take Notes:</strong><br>• NE vs Epi comparison:<br>• NE: α1 ↑↑↑ | β1 ↑ | β2 minimal<br>• Epi: α1 ↑↑ | β1 ↑↑ | β2 ↑↑<br>→ NE: SVR ↑↑ | No bronchodilation<br>→ Epi: CO ↑ | SVR variable | Bronchodilation"},
  {"q":"Which autonomic drug is commonly administered with neostigmine during reversal of neuromuscular blockade?","o":["Clonidine","Glycopyrrolate","Prazosin","Phenylephrine"],"a":1,"e":"Glycopyrrolate prevents neostigmine's muscarinic adverse effects (bradycardia, bronchospasm, excessive secretions) by blocking M2/M3 receptors without entering the CNS.<br><br><strong>Take Notes:</strong><br>• Reversal pair: Neostigmine + Glycopyrrolate<br>• Glycopyrrolate blocks: Bradycardia (M2) + Secretions (M3)<br>• Glycopyrrolate: Slower onset than atropine → Better matched to neostigmine onset<br>⚡ Atropine: Alternative but faster HR rise"},
  {"q":"Which receptor is primarily responsible for bronchodilation during administration of salbutamol?","o":["α1 receptor","β1 receptor","β2 receptor","M2 receptor"],"a":2,"e":"Salbutamol selectively stimulates β2 receptors in bronchial smooth muscle, activating Gs/adenylate cyclase/cAMP pathway to cause relaxation and bronchodilation.<br><br><strong>Take Notes:</strong><br>• Salbutamol: Selective β2 agonist<br>• Bronchodilation | Uterine relaxation<br>✅ Asthma: Reliever inhaler | Status asthmaticus: IV salbutamol<br>⚠️ Tachycardia at high doses (residual β1 activity)"},
  {"q":"Which α2 agonist is commonly used as an anaesthetic adjunct because of its sedative and analgesic properties?","o":["Prazosin","Phenylephrine","Dexmedetomidine","Propranolol"],"a":2,"e":"Dexmedetomidine is a highly selective α2 agonist (α2:α1 selectivity 1600:1) acting on locus coeruleus and spinal cord α2 receptors to produce cooperative sedation and analgesia.<br><br><strong>Take Notes:</strong><br>• Dexmedetomidine: Highly selective α2 agonist<br>• Sedation (cooperative, arousable) | Analgesia | Sympatholysis<br>• Minimal respiratory depression<br>✅ Awake intubation | ICU sedation | Opioid-sparing"},
  {"q":"Which drug is most likely to produce rebound hypertension if abruptly discontinued after chronic therapy?","o":["Atropine","Clonidine","Phenylephrine","Glycopyrrolate"],"a":1,"e":"Chronic clonidine suppresses central sympathetic outflow; abrupt withdrawal causes a surge in catecholamines as upregulated α2 receptors become unoccupied — producing severe rebound hypertension.<br><br><strong>Take Notes:</strong><br>• Clonidine withdrawal: Rebound severe HTN<br>• Mechanism: Upregulated sympathetic outflow + Receptor upregulation<br>⚠️ Can cause hypertensive crisis | MI | CVA<br>✅ Taper gradually | Continue peri-operatively"},
  {"q":"Which autonomic receptor subtype mediates relaxation of gastrointestinal smooth muscle?","o":["β2 receptor","α1 receptor","M3 receptor","M1 receptor"],"a":0,"e":"β2 receptor activation relaxes smooth muscle throughout the GI tract (and elsewhere), while M3 receptor activation contracts it — sympathetic inhibits GI motility, parasympathetic stimulates it.<br><br><strong>Take Notes:</strong><br>• β2: GI smooth muscle relaxation<br>• Sympathetic: GI motility ↓ | Sphincter contraction (α1)<br>• Parasympathetic (M3): GI motility ↑ | Sphincter relaxation"},
  {"q":"Which drug is most commonly used during anaesthesia to treat severe vagal bradycardia?","o":["Esmolol","Prazosin","Atropine","Clonidine"],"a":2,"e":"Atropine rapidly reverses vagal bradycardia by blocking M2 receptors in the cardiac conduction system — first-line for intraoperative bradycardia from any vagal cause.<br><br><strong>Take Notes:</strong><br>• Intraoperative bradycardia: Atropine first-line<br>• Acts in <30 sec IV<br>• Dose: 0.5–1 mg IV adult<br>⚡ Transplanted heart: Atropine ineffective (no vagal innervation) → Use epinephrine"},
  {"q":"Which adrenergic receptor subtype predominates in vascular smooth muscle?","o":["β2 receptor","α1 receptor","β1 receptor","M2 receptor"],"a":1,"e":"α1 receptors are the dominant postsynaptic adrenergic receptors on vascular smooth muscle — activation contracts smooth muscle, increases SVR and drives the sympathetic pressor response.<br><br><strong>Take Notes:</strong><br>• α1: Dominant vascular receptor<br>• Vasoconstriction → SVR ↑ | BP ↑<br>• Sympathetic activation → NE released → α1 → Pressor response"},
  {"q":"Which drug is a selective β1 blocker frequently used perioperatively?","o":["Propranolol","Prazosin","Metoprolol","Phenoxybenzamine"],"a":2,"e":"Metoprolol preferentially blocks β1 receptors (cardiac) at normal clinical doses, reducing HR and myocardial O₂ demand without the β2-mediated bronchospasm risk of propranolol.<br><br><strong>Take Notes:</strong><br>• Selective β1 blockers: Metoprolol | Atenolol | Bisoprolol | Esmolol<br>• HR ↓ | Contractility ↓ | MVO₂ ↓<br>✅ Perioperative cardiac protection<br>⚠️ Selectivity lost at high doses (β2 also blocked)"},
  {"q":"Which drug can cross the blood-brain barrier and reverse central anticholinergic toxicity?","o":["Glycopyrrolate","Physostigmine","Neostigmine","Pyridostigmine"],"a":1,"e":"Physostigmine is a tertiary amine AChE inhibitor that freely crosses the BBB — the only AChE inhibitor able to reverse central antimuscarinic toxicity (confusion, agitation, delirium).<br><br><strong>Take Notes:</strong><br>• Physostigmine: Crosses BBB (tertiary amine)<br>• Reverses: Central anticholinergic syndrome<br>• Dose: 1–2 mg IV slowly<br>⚡ Neostigmine/Glycopyrrolate/Pyridostigmine: Quaternary → BBB impermeable"},
  {"q":"Which adrenergic agonist has strong β1 and β2 activity with minimal α activity?","o":["Isoproterenol","Norepinephrine","Phenylephrine","Methoxamine"],"a":0,"e":"Isoproterenol is the prototypical non-selective β agonist — strong β1 (cardiac) and β2 (bronchial, vascular) activity with virtually no α receptor activity.<br><br><strong>Take Notes:</strong><br>• Isoproterenol: β1 + β2 | No α<br>• HR ↑↑ | CO ↑ | SVR ↓ | Bronchodilation<br>✅ Uses: Complete heart block | Torsades de pointes (increases HR)<br>⚠️ BP may fall despite CO ↑ (SVR ↓)"},
  {"q":"Which receptor subtype is responsible for pupillary dilation produced by phenylephrine?","o":["α1 receptor","β2 receptor","M2 receptor","M3 receptor"],"a":0,"e":"Phenylephrine stimulates α1 receptors on the radial (dilator pupillae) muscle of the iris, contracting it and enlarging the pupil — without blocking ciliary muscle accommodation.<br><br><strong>Take Notes:</strong><br>• Iris: α1 → Radial muscle contracts → Mydriasis<br>• No cycloplegia (ciliary muscle unaffected)<br>✅ Used in: Ophthalmology | Nasal decongestants"},
  {"q":"Which drug is classically used in phaeochromocytoma to achieve irreversible α blockade?","o":["Prazosin","Phenoxybenzamine","Atenolol","Esmolol"],"a":1,"e":"Phenoxybenzamine forms a permanent covalent bond with α receptors, producing long-lasting (24–48h) non-selective α blockade — used for 10–14 days preoperatively to control phaeochromocytoma hypertension.<br><br><strong>Take Notes:</strong><br>• Phenoxybenzamine: Irreversible non-selective α blocker<br>• Preoperative phaeochromocytoma prep (10–14 days)<br>⚠️ α block FIRST, then β block<br>⚡ Prazosin: Selective α1 but reversible"},
  {"q":"Which cholinesterase inhibitor is most commonly used to reverse nondepolarising neuromuscular blockade?","o":["Physostigmine","Donepezil","Neostigmine","Echothiophate"],"a":2,"e":"Neostigmine is the standard AChE inhibitor for NMB reversal — it increases ACh at the NMJ, competitively displacing residual NMB agent from nicotinic receptors.<br><br><strong>Take Notes:</strong><br>• Neostigmine: Standard NMB reversal agent<br>• Dose: 2.5 mg IV (with glycopyrrolate)<br>• Effective for TOF ratio <0.9<br>⚡ Sugammadex: Superior for rocuronium/vecuronium | Any depth of block"},
  {"q":"Which receptor subtype is primarily responsible for glycogenolysis in skeletal muscle?","o":["α2 receptor","β2 receptor","M3 receptor","β1 receptor"],"a":1,"e":"β2 receptor stimulation activates phosphorylase in skeletal muscle, breaking down glycogen to glucose-1-phosphate — providing rapid fuel during exercise or sympathetic activation.<br><br><strong>Take Notes:</strong><br>• β2 metabolic effects:<br>• Glycogenolysis ↑ (skeletal muscle)<br>• K⁺ uptake ↑ into cells (clinically: insulin + salbutamol treat hyperkalaemia)<br>• Gluconeogenesis ↑ | Lipolysis ↑"},
  {"q":"Which autonomic drug decreases sympathetic outflow from the central nervous system?","o":["Phenylephrine","Clonidine","Ephedrine","Atropine"],"a":1,"e":"Clonidine and dexmedetomidine stimulate central α2 receptors in the nucleus tractus solitarius — reducing sympathetic nerve firing and lowering blood pressure, heart rate and anxiety.<br><br><strong>Take Notes:</strong><br>• Central α2 agonists: Clonidine | Dexmedetomidine<br>• Sympatholysis: BP ↓ | HR ↓<br>• Analgesic-sparing | MAC ↓<br>⚠️ Clonidine: Abrupt withdrawal → Rebound HTN"},
  {"q":"Which receptor subtype mediates most parasympathetic effects on exocrine glands?","o":["β1 receptor","β2 receptor","M3 receptor","α2 receptor"],"a":2,"e":"M3 receptors on exocrine glands couple to Gq, activating IP3/DAG signalling to raise intracellular Ca²⁺ and stimulate secretion from salivary, lacrimal, gastric and other glands.<br><br><strong>Take Notes:</strong><br>• M3: Exocrine gland secretion<br>• Salivation ↑ | Lacrimation ↑ | Gastric acid ↑<br>✅ Blocked by: Atropine | Glycopyrrolate → Dry secretions<br>✅ Stimulated by: Pilocarpine → Glaucoma | Dry mouth treatment"},
  {"q":"Which β-blocker is contraindicated in severe bronchial asthma because of nonselective β blockade?","o":["Atenolol","Metoprolol","Propranolol","Bisoprolol"],"a":2,"e":"Propranolol blocks β2 receptors in bronchial smooth muscle — removing the sympathetic bronchodilatory tone and precipitating life-threatening bronchospasm in asthmatic patients.<br><br><strong>Take Notes:</strong><br>• Propranolol in asthma: Absolute contraindication<br>• β2 blockade → Bronchospasm<br>• Also: COPD relative CI<br>✅ Cardioselective β1 blockers safer: Metoprolol | Atenolol | Bisoprolol"},
  {"q":"Which adrenergic agonist is most commonly used during CPR?","o":["Epinephrine","Dobutamine","Isoproterenol","Salbutamol"],"a":0,"e":"Epinephrine is the cornerstone of advanced cardiac life support — its α1-mediated vasoconstriction raises coronary and cerebral perfusion pressure during CPR, improving the chance of ROSC.<br><br><strong>Take Notes:</strong><br>• CPR drug: Epinephrine<br>• α1: Aortic diastolic pressure ↑ → Coronary PP ↑<br>• β1: Myocardial contractility when circulation restored<br>✅ Dose: 1 mg IV every 3–5 min | Anaphylaxis: 0.5 mg IM"},
  {"q":"Which drug is often preferred over atropine during anaesthesia because it causes less tachycardia and no significant CNS effects?","o":["Glycopyrrolate","Phenylephrine","Clonidine","Ephedrine"],"a":0,"e":"Glycopyrrolate's quaternary structure prevents CNS penetration and its slower onset produces less abrupt heart rate changes than atropine — making it the standard perioperative antimuscarinic.<br><br><strong>Take Notes:</strong><br>• Glycopyrrolate advantages over atropine:<br>• No CNS effects (quaternary → BBB impermeable)<br>• Less tachycardia (slower onset)<br>• Better antisialagogue potency<br>✅ Preferred with neostigmine | Premedication"},
  {"q":"Which receptor subtype is primarily responsible for presynaptic inhibition of norepinephrine release?","o":["α1 receptor","α2 receptor","β1 receptor","β2 receptor"],"a":1,"e":"Presynaptic α2 autoreceptors on sympathetic nerve terminals detect NE in the synapse and inhibit further vesicle exocytosis — a homeostatic negative feedback mechanism.<br><br><strong>Take Notes:</strong><br>• α2 presynaptic autoreceptor: NE release ↓<br>• Negative feedback on sympathetic transmission<br>⚡ Clonidine stimulates central α2 → Sympathetic outflow ↓<br>• α-methyldopa: Central α2 agonist → Antihypertensive"},
  {"q":"During spinal anaesthesia-induced hypotension, a pure α1 agonist is administered. Which physiological change is expected?","o":["SVR decreases","Reflex tachycardia","SVR increases with possible reflex bradycardia","Bronchodilation"],"a":2,"e":"Pure α1 stimulation increases arteriolar tone and raises SVR — which triggers baroreceptor-mediated vagal activation, often producing reflex bradycardia as an unwanted side effect.<br><br><strong>Take Notes:</strong><br>• Phenylephrine (pure α1):<br>• SVR ↑ | BP ↑ | Reflex bradycardia<br>⚠️ If bradycardia symptomatic: Atropine 0.5 mg IV<br>✅ Spinal hypotension: Preferred over ephedrine in obstetrics"},
  {"q":"A patient undergoing anaesthesia develops hypotension. Which pure α1 agonist vasopressor is most appropriate?","o":["Esmolol","Phenylephrine","Prazosin","Glycopyrrolate"],"a":1,"e":"Phenylephrine is the most commonly used vasopressor in neuraxial-induced hypotension — its selective α1 agonism reliably restores SVR without tachycardia or direct myocardial stimulation.<br><br><strong>Take Notes:</strong><br>• Phenylephrine: First-line vasopressor for neuraxial hypotension<br>• Pure α1 | SVR ↑ | No direct cardiac stimulation<br>✅ Bolus: 50–100 μg IV | Infusion: 25–100 μg/min<br>⚠️ Reflex bradycardia possible"},
  {"q":"A patient undergoing carotid endarterectomy develops severe bradycardia after carotid sinus manipulation. Which mechanism is responsible?","o":["β1 receptor stimulation causing reflex vagal discharge","Activation of carotid baroreceptors causing increased parasympathetic outflow","α1 receptor stimulation causing SA node suppression","β2 receptor activation causing AV nodal blockade"],"a":1,"e":"Mechanical pressure on the carotid sinus baroreceptors sends afferent signals via the glossopharyngeal nerve to the medulla, which reflexively increases vagal efferent activity — slowing the SA node.<br><br><strong>Take Notes:</strong><br>• Carotid sinus reflex:<br>• Pressure → Baroreceptor firing ↑ → CN IX afferent → Vagal ↑<br>• HR ↓ + BP ↓<br>✅ Treatment: Stop stimulus | Atropine | Lidocaine infiltration at carotid sinus"},
  {"q":"During spinal anaesthesia, severe hypotension develops. Compared with ephedrine, phenylephrine is more likely to:","o":["Increase heart rate significantly","Increase cardiac output markedly","Cause reflex bradycardia","Produce bronchodilation"],"a":2,"e":"Phenylephrine's pure α1 action raises BP without any direct cardiac stimulation — triggering baroreceptor-mediated vagal reflex bradycardia, which distinguishes it clearly from ephedrine's mixed sympathomimetic profile.<br><br><strong>Take Notes:</strong><br>• Phenylephrine vs Ephedrine:<br>• Phenylephrine: α1 only → HR ↓ (reflex) | CO unchanged/↓<br>• Ephedrine: Mixed α + β → HR ↑ | CO ↑<br>✅ Obstetric spinal: Phenylephrine preferred (better fetal pH)"},
  {"q":"Which statement best explains why atropine may fail to produce a significant increase in heart rate in a transplanted heart?","o":["β1 receptors are absent","The heart lacks sympathetic innervation","The transplanted heart is denervated from vagal influences","Muscarinic receptors disappear after transplantation"],"a":2,"e":"Cardiac transplantation severs both vagal and sympathetic innervation — atropine blocks vagal (muscarinic) input that barely exists, producing minimal chronotropic response.<br><br><strong>Take Notes:</strong><br>• Transplanted heart: Denervated<br>• Atropine: Blocks absent vagal tone → Minimal HR effect<br>✅ Use: Direct β agonists (isoproterenol | epinephrine) for chronotropy<br>⚡ Resting HR ≈100 bpm (intrinsic SA rate without vagal tone)"},
  {"q":"A patient on chronic clonidine therapy abruptly stops. Severe hypertension develops 24 hours later. The most likely mechanism is:","o":["Muscarinic receptor upregulation","Rebound sympathetic overactivity","β1 receptor blockade","Catecholamine depletion"],"a":1,"e":"Chronic clonidine suppresses sympathetic activity and downregulates NE release — withdrawal upregulates sympathetic outflow and circulating catecholamines surge, causing severe rebound hypertension.<br><br><strong>Take Notes:</strong><br>• Clonidine withdrawal syndrome:<br>• Upregulated sympathetics surge → BP ↑↑↑ | HR ↑<br>⚠️ Can precipitate: Hypertensive crisis | MI | CVA<br>✅ Management: Resume clonidine | Labetalol or phentolamine for acute crisis"},
  {"q":"Which receptor subtype is primarily responsible for the vasoconstrictor response maintaining arterial pressure during haemorrhage?","o":["β2 receptor","M2 receptor","α1 receptor","D1 receptor"],"a":2,"e":"Haemorrhage triggers baroreceptor-mediated sympathetic activation — NE released from sympathetic nerves stimulates α1 receptors on arterioles, raising SVR to maintain MAP despite reduced blood volume.<br><br><strong>Take Notes:</strong><br>• Haemorrhage compensation: α1 vasoconstriction<br>• NE + Epi released → α1 → SVR ↑ → BP maintained<br>• Phenylephrine/NE mimic this response therapeutically<br>✅ RAAS + ADH: Delayed volume restoration"},
  {"q":"A patient receives neostigmine without glycopyrrolate during reversal. Which adverse effect is most likely?","o":["Severe bronchodilation","Marked tachycardia","Bradycardia and increased secretions","Hypertension and mydriasis"],"a":2,"e":"Neostigmine without antimuscarinic coverage increases ACh at M2 (cardiac) receptors causing bradycardia, and at M3 (glandular) receptors causing excessive saliva and bronchial secretions.<br><br><strong>Take Notes:</strong><br>• Neostigmine alone: Muscarinic side effects<br>• Bradycardia (M2) | Salivation ↑ (M3) | Secretions ↑<br>• Bronchospasm | Gut motility ↑<br>✅ Always pair with glycopyrrolate 0.2 mg per 2.5 mg neostigmine"},
  {"q":"Which adrenergic agonist would be expected to produce the greatest increase in myocardial oxygen consumption?","o":["Phenylephrine","Dobutamine","Clonidine","Glycopyrrolate"],"a":1,"e":"Dobutamine markedly increases heart rate, contractility and wall tension — all major determinants of myocardial oxygen consumption — making it potentially dangerous in patients with ischaemic heart disease.<br><br><strong>Take Notes:</strong><br>• Dobutamine: MVO₂ ↑↑<br>• Contractility ↑ | HR ↑ (mild) | Wall tension ↑<br>⚠️ Use cautiously in: IHD | Active ischaemia<br>✅ Benefit: CO ↑ in cardiogenic shock despite MVO₂ cost"},
  {"q":"Which receptor is the principal target responsible for the sedative effects of dexmedetomidine?","o":["β1 receptor","α1 receptor","α2 receptor in the locus coeruleus","M2 receptor"],"a":2,"e":"Dexmedetomidine acts on α2 receptors in the locus coeruleus — the brainstem 'arousal centre' — hyperpolarising these noradrenergic neurons and producing the characteristic cooperative, arousable sedation.<br><br><strong>Take Notes:</strong><br>• Dexmedetomidine sedation mechanism:<br>• Locus coeruleus α2 → ↓ NA firing → Sedation<br>• Spinal α2 → Analgesia<br>✅ Sedation resembles natural sleep (EEG-confirmed)<br>• Minimal respiratory depression"},
  {"q":"Why is glycopyrrolate generally preferred over atropine when reversing neuromuscular blockade?","o":["It is more potent at nicotinic receptors","It crosses the BBB more effectively","It produces less tachycardia and negligible CNS effects","It inhibits acetylcholinesterase"],"a":2,"e":"Glycopyrrolate's permanent positive charge (quaternary ammonium) prevents CNS penetration and its onset mirrors neostigmine's — preventing the inappropriate tachycardia seen when faster-acting atropine is paired with slower neostigmine.<br><br><strong>Take Notes:</strong><br>• Glycopyrrolate advantages in reversal:<br>• No CNS effects | Less tachycardia<br>• Similar onset to neostigmine (better matched)<br>✅ Standard pair: Neostigmine + Glycopyrrolate<br>⚡ If atropine used: Faster HR rise before neostigmine peaks"},
  {"q":"A patient with severe septic shock remains hypotensive despite adequate fluid resuscitation. Which receptor-mediated effect of norepinephrine is most useful?","o":["β2-mediated bronchodilation","α1-mediated vasoconstriction","M3-mediated vasoconstriction","D2-mediated renal vasodilation"],"a":1,"e":"In distributive (septic) shock, SVR is profoundly reduced — norepinephrine's potent α1 stimulation restores vascular tone, raises MAP and improves organ perfusion pressure.<br><br><strong>Take Notes:</strong><br>• Norepinephrine: First-line vasopressor for septic shock<br>• α1 → SVR ↑ → MAP ↑ → Organ perfusion restored<br>• Also β1 → Mild inotropy<br>✅ Target MAP ≥65 mmHg | Titrate to effect"},
  {"q":"Which β-blocker is most useful when a very short-lived reduction in heart rate is required during surgery?","o":["Propranolol","Atenolol","Metoprolol","Esmolol"],"a":3,"e":"Esmolol's t½ of ≈9 minutes from RBC esterase hydrolysis allows precise intraoperative titration — heart rate can be controlled and the effect wears off within 10–20 minutes if needed.<br><br><strong>Take Notes:</strong><br>• Esmolol: t½ ≈9 min | Ultra-titratable<br>• Intraoperative HR control | Laryngoscopy | Emergence<br>• Bolus: 0.5 mg/kg | Infusion: 50–300 μg/kg/min<br>✅ Not organ-dependent clearance (RBC esterases)"},
  {"q":"A patient develops bronchospasm after receiving propranolol. Which receptor blockade is responsible?","o":["α1 blockade","β1 blockade","β2 blockade","M2 blockade"],"a":2,"e":"Propranolol blocks β2 receptors in bronchial smooth muscle — removing the sympathetic bronchodilatory tone and allowing parasympathetic bronchoconstriction to dominate.<br><br><strong>Take Notes:</strong><br>• Propranolol: β2 blockade → Bronchospasm<br>⚠️ Asthma/COPD: Non-selective β blockers contraindicated<br>✅ Cardioselective β1 blockers safer: Atenolol | Metoprolol (at low doses)"},
  {"q":"Which autonomic receptor subtype is primarily responsible for aqueous humour production?","o":["β2 receptor","α1 receptor","M3 receptor","D1 receptor"],"a":0,"e":"β receptors in the ciliary epithelium stimulate aqueous humour production — topical β-blockers (timolol, betaxolol) reduce IOP by inhibiting this production.<br><br><strong>Take Notes:</strong><br>• β2: Aqueous humour production ↑<br>• β-blockers (timolol): Aqueous production ↓ → IOP ↓<br>✅ Glaucoma treatment<br>⚠️ Systemic absorption of timolol: Bradycardia | Bronchospasm"},
  {"q":"A patient develops profound bradycardia after intravenous dexmedetomidine. Which pharmacological property best explains this?","o":["Direct β1 stimulation","Central sympatholysis","Muscarinic receptor activation","α1 blockade"],"a":1,"e":"Dexmedetomidine stimulates central α2 receptors, markedly reducing sympathetic nerve firing — leaving parasympathetic tone relatively unopposed and producing significant bradycardia.<br><br><strong>Take Notes:</strong><br>• Dexmedetomidine bradycardia mechanism:<br>• Central α2 → Sympatholysis → Vagal predominance → HR ↓<br>⚠️ Avoid rapid bolus (may cause paradoxical HTN + severe bradycardia)<br>✅ Slow infusion: 0.2–0.7 μg/kg/h"},
  {"q":"Which receptor subtype is primarily responsible for relaxation of vascular smooth muscle in skeletal muscle beds?","o":["α1 receptor","α2 receptor","β2 receptor","M2 receptor"],"a":2,"e":"β2 receptors on skeletal muscle vasculature cause vasodilation via Gs/cAMP, increasing blood flow during sympathetic activation (exercise, stress) — the dominant mechanism in muscle beds.<br><br><strong>Take Notes:</strong><br>• β2: Skeletal muscle vasodilation<br>• Exercise response: Epi → β2 → Muscle blood flow ↑<br>⚡ α1: Skin/visceral vasoconstriction (opposite effect)"},
  {"q":"During treatment of anaphylaxis, epinephrine is beneficial because it simultaneously stimulates:","o":["α1, β1, and β2 receptors","M2 and M3 receptors","α2 receptors only","D1 receptors only"],"a":0,"e":"Epinephrine simultaneously reverses all components of anaphylaxis: α1 vasoconstriction reverses the vasodilation, β1 supports cardiac output, and β2 relieves bronchospasm and inhibits mediator release.<br><br><strong>Take Notes:</strong><br>• Anaphylaxis: Epinephrine's multi-receptor action<br>• α1: SVR ↑ → BP restored | Oedema ↓<br>• β1: CO ↑ → Circulatory support<br>• β2: Bronchodilation | Mast cell stabilisation<br>✅ Dose: 0.5 mg IM (1:1000) | Repeat as needed"},
  {"q":"Which autonomic drug has become increasingly popular in anaesthesia because it provides sedation with minimal respiratory depression?","o":["Morphine","Midazolam","Dexmedetomidine","Thiopentone"],"a":2,"e":"Dexmedetomidine produces a unique 'cooperative' sedation via central α2 receptors — patients are arousable, follow commands, and critically maintain their spontaneous ventilation.<br><br><strong>Take Notes:</strong><br>• Dexmedetomidine unique properties:<br>• Sedation with preserved ventilation<br>• No respiratory depression at clinical doses<br>✅ Uses: Awake intubation | ICU sedation | Opioid-sparing | MAC procedures"},
  {"q":"A patient with phaeochromocytoma is prepared for surgery. Why must β-blockers never be started before adequate α-blockade?","o":["Severe bradycardia occurs immediately","Unopposed α stimulation may precipitate severe hypertension","Pulmonary oedema always develops","Renal failure becomes inevitable"],"a":1,"e":"Phaeochromocytoma secretes NE and Epi; β-blockade removes cardiac β and vascular β2 effects while leaving α1 vasoconstriction completely unopposed — causing potentially fatal hypertensive crisis.<br><br><strong>Take Notes:</strong><br>• Phaeochromocytoma rule: α block FIRST then β<br>• β block alone → Unopposed α1 → Vasoconstriction ↑↑↑ → HTN crisis<br>✅ Protocol: Phenoxybenzamine 10–14 days → Then propranolol/atenolol<br>⚠️ This is a frequently examined examination concept"},
  {"q":"Which receptor subtype is responsible for most parasympathetic-mediated bronchoconstriction?","o":["M3 receptor","β2 receptor","α1 receptor","D1 receptor"],"a":0,"e":"M3 receptors on airway smooth muscle couple to Gq/PLC/IP3, raising intracellular Ca²⁺ and producing bronchoconstriction — the mechanism blocked by ipratropium (antimuscarinic bronchodilator).<br><br><strong>Take Notes:</strong><br>• M3: Bronchoconstriction<br>• Secretions ↑ | Smooth muscle contraction<br>✅ Ipratropium (M3 blocker): COPD/Asthma bronchodilator<br>⚡ β2 (salbutamol): Opposite effect → Bronchodilation"},
  {"q":"A patient under general anaesthesia develops severe hypotension and bradycardia due to excessive vagal stimulation during peritoneal traction. What is the primary disturbance?","o":["Increased β1 activity and reduced vagal tone","Increased parasympathetic activity with suppression of SA node firing","Increased α1 stimulation causing reflex tachycardia","Increased β2 stimulation causing vasoconstriction"],"a":1,"e":"Peritoneal traction activates vagal afferents from visceral receptors — triggering a powerful parasympathetic reflex causing SA node suppression, AV conduction slowing, peripheral vasodilation and hypotension.<br><br><strong>Take Notes:</strong><br>• Visceral/Peritoneal traction reflex:<br>• Vagal afferents activated → SA node suppression → Bradycardia + Hypotension<br>✅ Treatment: Stop traction | Atropine 0.5–1 mg IV<br>⚠️ Can cause asystole — always respond promptly"},
  {"q":"A patient with severe septic shock receiving high-dose norepinephrine has poor peripheral perfusion. Which receptor action maintains blood pressure?","o":["β2-mediated vasodilation","M3-mediated vasoconstriction","α1-mediated vasoconstriction","D1-mediated renal vasodilation"],"a":2,"e":"Norepinephrine's dominant therapeutic action in septic shock is potent α1-mediated arteriolar vasoconstriction, restoring SVR and MAP to maintain coronary and cerebral perfusion pressure.<br><br><strong>Take Notes:</strong><br>• Norepinephrine receptor profile:<br>• α1 ↑↑↑ (dominant) | β1 ↑ (moderate) | β2 minimal<br>✅ Septic shock: NE = First-line vasopressor (Surviving Sepsis)<br>• Target: MAP ≥65 mmHg"},
  {"q":"Which autonomic receptor subtype contributes most significantly to the positive chronotropic effect of epinephrine?","o":["α1 receptor","β1 receptor","β2 receptor","M2 receptor"],"a":1,"e":"Epinephrine's positive chronotropic effect is mediated primarily through β1 receptors in the SA node — increasing automaticity and heart rate.<br><br><strong>Take Notes:</strong><br>• Epinephrine: β1 → SA node ↑ → HR ↑<br>• Also: β1 → AV conduction ↑ (dromotropy)<br>• β1 → Contractility ↑ (inotropy)"},
  {"q":"A patient develops severe bradycardia during laparoscopic insufflation. Which physiological mechanism is most likely involved?","o":["β1 receptor blockade","Increased vagal discharge from peritoneal stretch","α1 receptor stimulation","β2 receptor activation"],"a":1,"e":"Rapid peritoneal distension during pneumoperitoneum mechanically stretches vagal afferents, triggering a powerful vasovagal reflex causing sudden bradycardia — occasionally progressing to asystole.<br><br><strong>Take Notes:</strong><br>• Laparoscopy vagal reflex:<br>• Peritoneal stretch → Vagal ↑ → HR ↓<br>⚠️ Can cause asystole — pause insufflation immediately<br>✅ Treatment: Atropine | Reduce intra-abdominal pressure"},
  {"q":"Which characteristic best explains the usefulness of dexmedetomidine during awake fibreoptic intubation?","o":["Produces profound respiratory depression","Causes complete amnesia only","Provides cooperative sedation with preserved ventilation","Produces neuromuscular blockade"],"a":2,"e":"Dexmedetomidine produces an arousable, cooperative sedation where patients can follow commands and maintain spontaneous ventilation — critical requirements for successful awake airway management.<br><br><strong>Take Notes:</strong><br>• Dexmedetomidine for awake intubation:<br>• Cooperative sedation (arousable)<br>• Ventilation preserved<br>• Anxiolysis + Analgesia (α2 spinal)<br>✅ Combined with topical lidocaine for awake FOI"},
  {"q":"A patient with phaeochromocytoma develops hypertension and tachycardia during tumour manipulation. Which endogenous catecholamine is most commonly responsible?","o":["Acetylcholine","Histamine","Norepinephrine","Glycine"],"a":2,"e":"Most phaeochromocytomas (70%) predominantly secrete norepinephrine from the adrenal medulla or extra-adrenal paraganglia, causing sustained or paroxysmal hypertension.<br><br><strong>Take Notes:</strong><br>• Phaeochromocytoma catecholamine:<br>• NE most common (70%) | Epi less common<br>• Symptoms: HTN | Sweating | Tachycardia | Headache<br>✅ α-block before surgery prevents intraoperative HTN crisis"},
  {"q":"Which autonomic receptor subtype is most important in mediating presynaptic negative feedback of sympathetic neurotransmission?","o":["β1 receptor","β2 receptor","α2 receptor","M3 receptor"],"a":2,"e":"Presynaptic α2 autoreceptors on sympathetic nerve terminals sense NE in the synapse and feed back to inhibit further NE release — a homeostatic mechanism limiting excessive sympathetic activity.<br><br><strong>Take Notes:</strong><br>• α2 presynaptic autoreceptor:<br>• NE ↑ in synapse → α2 activated → NE release ↓<br>• Prevents runaway sympathetic activation<br>✅ Clonidine stimulates this → Sympatholysis"},
  {"q":"During anaesthesia, a patient develops profound bronchospasm. Which autonomic agonist would produce the most rapid bronchodilation?","o":["Phenylephrine","Salbutamol","Atropine","Prazosin"],"a":1,"e":"Salbutamol (β2 agonist) directly relaxes bronchial smooth muscle via Gs/cAMP — the fastest and most effective treatment for acute bronchospasm in an anaesthetised patient.<br><br><strong>Take Notes:</strong><br>• Bronchospasm during anaesthesia:<br>• Salbutamol: β2 → Bronchodilation (first-line inhaled/IV)<br>• Also: Deepen anaesthesia (volatile) | Epinephrine (severe)<br>✅ IV salbutamol: 250 μg slow IV for severe bronchospasm"},
  {"q":"Which drug used in anaesthesia commonly causes dry mouth through muscarinic receptor blockade?","o":["Glycopyrrolate","Dobutamine","Ephedrine","Isoproterenol"],"a":0,"e":"Glycopyrrolate blocks M3 receptors on salivary glands, inhibiting ACh-stimulated secretion and producing a dry mouth — a desired effect when used as premedication antisialagogue.<br><br><strong>Take Notes:</strong><br>• Glycopyrrolate → M3 blockade → Dry mouth<br>• Desired when: Antisialagogue premedication | Airway procedures<br>• Undesired: Patient discomfort<br>✅ Dose: 0.2 mg IV or 0.2–0.4 mg IM"},
  {"q":"A patient receives phenylephrine for spinal hypotension. Which haemodynamic pattern is most likely?","o":["SVR ↓, HR ↑","SVR ↑, reflex HR ↓","CO ↑ markedly, SVR unchanged","Bronchodilation and tachycardia"],"a":1,"e":"Pure α1 stimulation raises SVR and MAP — this activates aortic and carotid baroreceptors which reflexively increase vagal tone, lowering heart rate as a compensatory response.<br><br><strong>Take Notes:</strong><br>• Phenylephrine haemodynamic profile:<br>• SVR ↑ → BP ↑ → Baroreceptors → Vagal ↑ → HR ↓<br>• CO: Unchanged or mildly ↓<br>⚠️ Symptomatic reflex bradycardia: Atropine 0.5 mg IV"},
  {"q":"Which receptor subtype predominates in the SA node?","o":["α1 receptor","β1 receptor","β2 receptor","M3 receptor"],"a":1,"e":"β1 receptors are the dominant sympathetic receptors in the SA node and conduction system — their stimulation accelerates the pacemaker potential and increases heart rate.<br><br><strong>Take Notes:</strong><br>• SA node dominant receptors:<br>• β1: HR ↑ (sympathetic) | Adrenergic<br>• M2: HR ↓ (parasympathetic) | Cholinergic<br>✅ β-blockers (β1): HR ↓ | Atropine (M2 block): HR ↑"},
  {"q":"Which autonomic drug is most useful for treatment of symptomatic bradycardia caused by excessive vagal stimulation?","o":["Prazosin","Clonidine","Atropine","Phenoxybenzamine"],"a":2,"e":"Atropine is the first-line drug for all forms of vagally mediated bradycardia — it competitively blocks M2 receptors at the SA and AV nodes, rapidly restoring heart rate.<br><br><strong>Take Notes:</strong><br>• Vagal bradycardia: Atropine first-line<br>• Dose: 0.5–1 mg IV | Repeatable<br>⚡ Transplanted heart: Use epinephrine (no vagal innervation)<br>✅ Alternative: Glycopyrrolate 0.2–0.4 mg IV"},
  {"q":"Why is ephedrine sometimes less effective after repeated dosing during prolonged anaesthesia?","o":["β1 receptor destruction","Catecholamine depletion from nerve terminals","Increased vagal activity","α1 receptor blockade"],"a":1,"e":"Ephedrine's indirect sympathomimetic action depends on displacing NE from presynaptic vesicles — repeated dosing empties these stores, producing tachyphylaxis (diminishing response).<br><br><strong>Take Notes:</strong><br>• Ephedrine tachyphylaxis:<br>• Indirect action depletes NE stores<br>• Subsequent doses less effective<br>⚡ Phenylephrine: Direct α1 → No tachyphylaxis<br>✅ Switch to phenylephrine for persistent hypotension"},
  {"q":"Which autonomic receptor subtype mediates contraction of the radial muscle of the iris?","o":["M3 receptor","β2 receptor","α1 receptor","M2 receptor"],"a":2,"e":"The radial (dilator pupillae) muscle contains α1 receptors — sympathetic activation or phenylephrine application causes contraction, pulling the pupil open (mydriasis).<br><br><strong>Take Notes:</strong><br>• Iris α1: Radial muscle → Mydriasis<br>• Sphincter pupillae: M3 → Miosis (parasympathetic)<br>✅ Phenylephrine ophthalmic drops: Mydriasis without cycloplegia"},
  {"q":"A patient on chronic β-blocker therapy receives epinephrine. Which receptor-mediated effect may still produce significant vasoconstriction?","o":["β2 receptor stimulation","α1 receptor stimulation","M2 receptor stimulation","D1 receptor stimulation"],"a":1,"e":"β-blockade removes cardiac and vasodilatory β effects of epinephrine, leaving α1-mediated vasoconstriction unopposed — potentially causing paradoxical severe hypertension.<br><br><strong>Take Notes:</strong><br>• β-blocker + Epinephrine: Unopposed α1 effects<br>⚠️ Classic interaction: Adrenaline in allergic patient on β-blocker → Severe HTN<br>✅ Use: Glucagon 1 mg IV (works independently of adrenergic receptors)"},
  {"q":"Which autonomic receptor is primarily responsible for increasing AV nodal conduction velocity?","o":["β1 receptor","α2 receptor","M3 receptor","α1 receptor"],"a":0,"e":"β1 receptors in the AV node increase positive dromotropy — accelerating conduction velocity and shortening the PR interval, the mechanism by which sympathetic activation facilitates rapid heart rates.<br><br><strong>Take Notes:</strong><br>• β1: AV nodal dromotropy ↑<br>• PR interval ↓<br>⚡ M2 (vagal): AV block ↑ → PR ↑<br>✅ β-blockers: PR ↑ | Atropine: PR ↓"},
  {"q":"Which drug would be expected to reduce anaesthetic requirements because of its central sympatholytic and sedative effects?","o":["Phenylephrine","Clonidine","Ephedrine","Dobutamine"],"a":1,"e":"Clonidine reduces MAC for volatile agents by 25–50% through central sympatholytic (reduced catecholamine release) and sedative (locus coeruleus suppression) mechanisms.<br><br><strong>Take Notes:</strong><br>• Clonidine: MAC reducer<br>• Sedation + Sympatholysis + Analgesia-sparing<br>• MAC ↓ 25–50%<br>✅ Used for: Perioperative anxiolysis | Opioid-sparing | PONV prophylaxis"},
  {"q":"A patient develops severe hypertension during emergence. Which ultra-short-acting β1 blocker is particularly useful?","o":["Atenolol","Esmolol","Propranolol","Phenoxybenzamine"],"a":1,"e":"Esmolol's t½ of ≈9 minutes allows precise titration during the dynamic period of emergence — heart rate and blood pressure can be rapidly controlled and the effect terminates quickly if needed.<br><br><strong>Take Notes:</strong><br>• Esmolol for emergence HTN:<br>• t½ ≈9 min | Precise titration<br>• Bolus 0.5–1 mg/kg | Infusion 50–200 μg/kg/min<br>✅ Ideal when temporary HR/BP control needed"},
  {"q":"Which receptor subtype is responsible for increased insulin secretion from pancreatic β-cells?","o":["α2 receptor","β2 receptor","α1 receptor","M2 receptor"],"a":1,"e":"β2 receptor stimulation in pancreatic β-cells increases insulin secretion via cAMP — while presynaptic α2 receptor stimulation (e.g., by hyperglycaemia-triggered NE) inhibits insulin release.<br><br><strong>Take Notes:</strong><br>• Pancreatic receptors:<br>• β2 → Insulin ↑<br>• α2 → Insulin ↓<br>✅ Clinical: Salbutamol → K⁺ shift into cells (insulin-independent) | Treats hyperkalaemia"},
  {"q":"During severe anaphylaxis, epinephrine improves bronchospasm primarily through stimulation of:","o":["α1 receptors","β1 receptors","β2 receptors","M3 receptors"],"a":2,"e":"β2 receptor activation in bronchial smooth muscle is the primary mechanism of epinephrine's bronchodilatory effect in anaphylaxis — directly counteracting the massive mediator-induced bronchoconstriction.<br><br><strong>Take Notes:</strong><br>• Anaphylaxis: Epinephrine β2 → Bronchodilation<br>• Also: β2 → Mast cell mediator release ↓<br>✅ Primary treatment: 0.5 mg IM adrenaline (1:1000) | Lateral thigh<br>⚠️ β-blocked patients: Bronchospasm may be refractory"},
  {"q":"During a prolonged abdominal procedure, traction on the mesentery produces sudden bradycardia, hypotension, and ventricular escape beats. Which immediate treatment is most appropriate?","o":["Propranolol","Prazosin","Atropine","Clonidine"],"a":2,"e":"Mesenteric traction triggers a powerful vago-vagal reflex — immediate cessation of surgical stimulus and IV atropine are the standard initial management for this perioperative emergency.<br><br><strong>Take Notes:</strong><br>• Mesenteric/Visceral traction reflex:<br>• Vagal surge → SA suppression → Bradycardia + Hypotension<br>✅ Immediate: Stop traction | Atropine 0.5–1 mg IV<br>⚠️ Can progress to asystole if untreated"},
  {"q":"Which adrenergic agonist is most suitable when both bronchospasm and hypotension coexist during anaesthesia?","o":["Phenylephrine","Salbutamol","Atropine","Epinephrine"],"a":3,"e":"Epinephrine simultaneously reverses bronchospasm (β2) and supports blood pressure (α1 + β1) — the ideal agent when both problems coexist as in severe anaphylaxis or refractory status asthmaticus with cardiovascular compromise.<br><br><strong>Take Notes:</strong><br>• Epinephrine: α1 + β1 + β2 — All three receptors targeted<br>• Bronchospasm + Hypotension = Epinephrine<br>✔ Dose: 0.5 mg IM (anaphylaxis) | 0.1 mg IV bolus (perioperative)"}
];